SELECT CASE WHEN ss.revenue >= 4200 THEN 'high' WHEN ss.revenue >= 800 THEN 'mid' ELSE 'low' END AS revenue_bucket, MAX(i.quantity) AS max_quantity, COUNT(i.quantity) AS quantity_count FROM inventory i INNER JOIN store_sales ss ON i.store_id = ss.store_id AND i.product_id = ss.product_id WHERE ss.product_id IN (5, 6) GROUP BY CASE WHEN ss.revenue >= 4200 THEN 'high' WHEN ss.revenue >= 800 THEN 'mid' ELSE 'low' END ORDER BY revenue_bucket DESC;
